local _, ns = ...
local Translate = ns.Lore.Translate

Translate("esMX", "humans", {
	title = "Humanos",
	sections = {
		{
			title = "Resumen",
			text = [=[Los humanos son el más numeroso de los pueblos jóvenes de los {link:eastern-kingdoms}Reinos del Este{/link}. Su vida es breve al lado de la de elfos y enanos, pero son inquietos, tenaces y rápidos para aprender. De sus linajes surgieron los grandes reinos del norte y del sur, y de sus filas salieron los paladines de la {link:holy-light}Luz Sagrada{/link} y los magos de {link:city-of-dalaran}Dalaran{/link}. Han sufrido más que ningún otro pueblo en las guerras contra los orcos y los no-muertos, y todavía no se han quebrado.]=],
		},
		{
			title = "Orígenes",
			text = [=[En tiempos antiguos, los humanos vivían como tribus dispersas en el norte, cada una desconfiada de las demás. Solo la tribu {link:arathi-highlands}Arathi{/link} vio que el imperio {link:trolls}trol{/link} de los Amani las destruiría una a una. Su caudillo {link:thoradin}Thoradin{/link} unió a las tribus por la fuerza y por la persuasión, y sobre esa unión fundó la nación de {link:arathor}Arathor{/link} y su ciudad fortaleza de {link:stromgarde-keep}Strom{/link}. Cuando los Amani atacaron a los {link:high-elves}altos elfos{/link} de {link:quel-thalas}Quel'Thalas{/link}, Arathor respondió a la llamada de los elfos. Los elfos enseñaron a cien humanos los caminos de la {link:arcane-magic}magia arcana{/link}, y juntos los dos pueblos quebraron a los Amani en las {link:troll-wars}Guerras Trol{/link}.

En la larga paz que siguió, la unidad de Arathor se desvaneció. Su pueblo se extendió por la tierra y fundó nuevos reinos: {link:lordaeron}Lordaeron{/link} en el norte, {link:gilneas}Gilneas{/link} y {link:kul-tiras}Kul Tiras{/link} en las costas occidentales, {link:alterac-mountains}Alterac{/link} y Stromgarde en las montañas, {link:city-of-dalaran}la ciudad de los magos{/link} en Dalaran y, en el lejano sur, el reino de {link:azeroth}Azeroth{/link}, al que hoy los hombres llaman {link:kingdom-of-stormwind}Reino de Ventormenta{/link}.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los humanos son un pueblo de reyes y de campesinos. Sus nobles conservan casas antiguas y rencillas más antiguas aún, y el pueblo llano trabaja la tierra sin pensar mucho en unas ni en otras. La iglesia de la {link:holy-light}Luz Sagrada{/link} une a muchos de ellos, y sus sacerdotes están en cada aldea. Los humanos valoran los juramentos, el valor y el deber, aunque no siempre los cumplan. Su mayor don es que reconstruyen. Todo lo que se quema, lo levantan de nuevo.]=],
		},
		{
			title = "En el presente",
			text = [=[Los reinos humanos son sombras de su antigua gloria. La {link:scourge}Plaga{/link} ocupa las ruinas de {link:lordaeron}Lordaeron{/link}, y la {link:scarlet-crusade}Cruzada Escarlata{/link} libra su propia guerra despiadada en el norte. {link:gilneas}Gilneas{/link} se ha encerrado tras su gran muralla. {link:alterac-mountains}Alterac{/link} está en ruinas, y {link:stromgarde-keep}Stromgarde{/link} se aferra a lo que queda de las {link:arathi-highlands}Tierras Altas de Arathi{/link}. En el sur, {link:stormwind-city}Ventormenta{/link} se alza reconstruida, pero el rey {link:varian-wrynn}Varian Wrynn{/link} ha desaparecido, y el alto señor {link:bolvar-fordragon}Bolvar Fordragon{/link} gobierna en su nombre. Al otro lado del mar, Lady {link:jaina-proudmoore}Jaina Proudmoore{/link} guarda la fortaleza isleña de {link:theramore-isle}Theramore{/link}, donde los humanos mantienen una paz inquieta con la {link:horde}Horda{/link}. La humanidad sigue siendo el corazón de la {link:alliance}Alianza{/link}, y es un corazón que sangra.]=],
		},
	},
})

Translate("esMX", "dwarves", {
	title = "Enanos",
	aliases = { "enano" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los enanos son un pueblo robusto y resistente de las montañas de Khaz Modan. Son mineros, herreros, cerveceros y guerreros, y están entre los mejores artesanos del mundo. Su gran ciudad de {link:ironforge}Forjaz{/link} está tallada en el corazón de una montaña. Han luchado junto a la humanidad desde la {link:second-war}Segunda Guerra{/link}, y siguen siendo uno de los pilares de la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[Durante eras, los enanos vivieron bajo las montañas, y sus propias leyendas decían que habían sido moldeados en piedra. En las salas de {link:uldaman}Uldaman{/link}, los eruditos de la {link:explorers-league}Liga de Expedicionarios{/link} han hallado registros de los titanes que parecen confirmarlo: hablan de los terráneos, seres de roca viva creados por los titanes para dar forma a los lugares profundos del mundo. Muchos enanos creen ahora que su pueblo desciende de ellos.

Los enanos estuvieron largo tiempo unidos bajo un único gran rey en {link:ironforge}Forjaz{/link}. Cuando ese rey murió, tres grandes clanes fueron a la guerra por su trono. En esta Guerra de los Tres Martillos, el clan Barbabronce se quedó con Forjaz. El clan Martillo Salvaje fue expulsado al norte y con el tiempo se asentó en las {link:the-hinterlands}Tierras del Interior{/link}. El {link:dark-iron-dwarves}clan Hierro Negro{/link} fue arrojado al sur. Allí su rey hechicero, {link:ruins-of-thaurissan}Thaurissan{/link}, buscó un poder con el que vengar su derrota, e invocó a {red:ragnaros}Ragnaros{/red}, el Señor del Fuego. El fuego de aquella invocación quebró la tierra y ató a los Hierro Negro al servicio del Señor del Fuego.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los enanos son orgullosos, leales y lentos para perdonar. Aman la buena cerveza, las canciones a voz en cuello y un hacha bien hecha. Respetan más los hechos que las palabras y son conocidos por su larga memoria. Sus armeros son famosos en todos los {link:eastern-kingdoms}Reinos del Este{/link}, y sus rifles y cañones han defendido muchas murallas. Los Martillo Salvaje son más salvajes que sus parientes y cabalgan grifos en la batalla, mientras que los Barbabronce prefieren la forja y el rifle.]=],
		},
		{
			title = "En el presente",
			text = [=[El rey {link:magni-bronzebeard}Magni Bronzebeard{/link} gobierna en {link:ironforge}Forjaz{/link}. Su hermano {link:brann-bronzebeard}Brann Bronzebeard{/link} dirige la {link:explorers-league}Liga de Expedicionarios{/link}, cuyos excavadores escarban en ruinas de todo el mundo en busca del verdadero pasado de los enanos. Forjaz ha abierto sus puertas a los {link:gnomes}gnomos{/link} que perdieron su ciudad a manos de los {link:troggs}troggs{/link}, y la Ciudad Manitas resuena ahora con el trabajo gnómico. Los {link:dark-iron-dwarves}Enanos Hierro Negro{/link} siguen siendo los enemigos más acérrimos de sus primos, y en las profundidades de la {link:blackrock-mountain}Montaña Roca Negra{/link} trabajan al servicio del Señor del Fuego. Los Martillo Salvaje siguen su propio consejo en las {link:the-hinterlands}Tierras del Interior{/link}, aliados de Forjaz pero nunca sus súbditos.]=],
		},
	},
})

Translate("esMX", "gnomes", {
	title = "Gnomos",
	aliases = { "gnomo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los gnomos son un pueblo pequeño, ingenioso y de curiosidad infinita. Son los mayores manitas e ingenieros del mundo, y en todo lo que encuentran ven un problema por resolver. Durante generaciones vivieron en la maravillosa ciudad de {link:gnomeregan}Gnomeregan{/link}, en las montañas de {link:dun-morogh}Dun Morogh{/link}. Esa ciudad está perdida para ellos, y ahora viven como huéspedes de los {link:dwarves}enanos{/link} en {link:ironforge}Forjaz{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los gnomos han sido desde hace mucho vecinos y amigos de los enanos de Khaz Modan. De sus primeros días, las historias de {link:azeroth}Azeroth{/link} dicen poco. Lo que es seguro es que construyeron {link:gnomeregan}Gnomeregan{/link} con sus propias manos y la llenaron de maravillas: grandes máquinas, sirvientes de relojería y artefactos que ningún otro pueblo habría podido imaginar. En la {link:second-war}Segunda Guerra{/link} se unieron a la {link:alliance}Alianza{/link} junto a los enanos. Enviaron pocos soldados, pues no son un pueblo numeroso, pero dieron a la Alianza máquinas voladoras, submarinos y armas de su propio diseño.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los gnomos son brillantes, rápidos y alegres incluso en las horas más oscuras. También se distraen con facilidad, y sus inventos no siempre hacen lo que sus creadores pretendían. Aprecian el ingenio por encima de la fuerza, y tienen a sus maestros ingenieros en el más alto honor. Su líder lleva el título de Manitas Mayor. Muchos gnomos estudian también la {link:arcane-magic}magia arcana{/link}, y algunos se vuelven hacia artes más oscuras que otros creen mejor dejar en paz.]=],
		},
		{
			title = "En el presente",
			text = [=[Tras la {link:third-war}Tercera Guerra{/link}, los {link:troggs}troggs{/link} surgieron de debajo de la tierra e inundaron {link:gnomeregan}Gnomeregan{/link}. La ciudad no pudo defenderse. El Manitas Mayor {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} tomó una decisión desesperada y desató un arma tóxica para expulsar a los invasores. Mató a muchos troggs, pero también a muchísimos gnomos, y dejó la ciudad envenenada. Los supervivientes huyeron a {link:ironforge}Forjaz{/link}. Ahora se susurra que la caída no fue un accidente: se dice que el propio consejero del Manitas Mayor, {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}, traicionó a su pueblo, y que ahora gobierna la ciudad en ruinas como su amo enloquecido. Los gnomos sueñan con el día en que recuperarán su hogar. Hasta entonces, construyen artilugios en Forjaz y sirven a la {link:alliance}Alianza{/link} con el mismo celo que siempre han mostrado.]=],
		},
	},
})

Translate("esMX", "night-elves", {
	title = "Elfos de la noche",
	aliases = { "kaldorei", "kal'dorei", "elfo de la noche" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los elfos de la noche, que se llaman a sí mismos kaldorei o "hijos de las estrellas", son el pueblo civilizado más antiguo de {link:kalimdor}Kalimdor{/link}. Son altos, de piel violácea y longevos, y han guardado los bosques del norte durante diez mil años. Sus sacerdotisas sirven a la diosa de la luna, Elune, y sus druidas cuidan lo salvaje según los caminos enseñados por el semidiós {link:cenarius}Cenarius{/link}. Tras la {link:third-war}Tercera Guerra{/link}, se unieron a la {link:alliance}Alianza{/link} por primera vez en su historia.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los primeros elfos de la noche fueron una tribu que se asentó a orillas del {link:well-of-eternity}Pozo de la Eternidad{/link} en tiempos antiguos. El poder del Pozo los cambió y les dio una larga vida. En sus orillas alzaron un gran imperio, gobernado por la {link:queen-azshara}reina Azshara{/link} y su casta de hechiceros Altonato. Los Altonato se embriagaron con el poder del Pozo, y al final su magia atrajo la mirada de la {link:burning-legion}Legión Ardiente{/link}. {link:azshara}Azshara{/link} abrió el camino a los demonios, y comenzó la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.

El druida {link:malfurion-stormrage}Malfurion Stormrage{/link}, la sacerdotisa {link:tyrande-whisperwind}Tyrande Whisperwind{/link} y sus aliados hicieron retroceder a la Legión. Al final, el Pozo fue destruido, y la {link:great-sundering}Gran Fractura{/link} hizo pedazos el antiguo continente. Los elfos de la noche que sobrevivieron dieron la espalda a la magia arcana. En el {link:mount-hyjal}Monte Hyjal{/link} cuidaron un nuevo árbol de la vida, {link:nordrassil}Nordrassil{/link}, que les concedió la inmortalidad. Los Altonato que se negaron a renunciar a su magia fueron enviados al exilio al otro lado del mar.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los elfos de la noche son un pueblo paciente y vigilante. Sus mujeres han servido desde hace mucho como {link:sentinels}Centinelas{/link}, las guerreras que guardan los bosques, mientras que sus hombres se hicieron druidas que dormían durante largos años en el {link:emerald-dream}Sueño Esmeralda{/link}. Aman los lugares salvajes del mundo y odian a quienes los expolian. No confían en lo arcano, pues estuvo a punto de acabar con su mundo.]=],
		},
		{
			title = "En el presente",
			text = [=[En la {link:third-war}Tercera Guerra{/link}, la Legión regresó. En la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, elfos de la noche, humanos y orcos se unieron contra {link:archimonde}Archimonde{/link}, y el poder de {link:nordrassil}Nordrassil{/link} se consumió para destruirlo. Con él, los elfos de la noche perdieron su inmortalidad. El archidruida {link:fandral-staghelm}Fandral Staghelm{/link} y sus druidas alzaron entonces un nuevo Árbol del Mundo, {link:teldrassil}Teldrassil{/link}, frente a la costa norte, y la ciudad de {link:darnassus}Darnassus{/link} creció en sus ramas. {link:tyrande-whisperwind}Tyrande{/link} gobierna allí como Suma Sacerdotisa, mientras {link:malfurion-stormrage}Malfurion{/link} recorre el {link:emerald-dream}Sueño Esmeralda{/link} y no ha regresado. Los kaldorei se enfrentan ahora a los orcos que talan los bosques de {link:ashenvale}Vallefresno{/link} y a la corrupción que se extiende por {link:felwood}Frondavil{/link}.]=],
		},
	},
})

Translate("esMX", "orcs", {
	title = "Orcos",
	aliases = { "orco" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los orcos son un orgulloso pueblo guerrero del mundo de Draenor. Llegaron a {link:azeroth}Azeroth{/link} como conquistadores a través del {link:dark-portal}Portal Oscuro{/link}, y trajeron fuego y ruina a los reinos humanos. Fueron derrotados, encarcelados y quebrados, y aun así se alzaron de nuevo. Bajo su Jefe de Guerra {link:thrall}Thrall{/link} han cruzado el mar hasta {link:kalimdor}Kalimdor{/link} y han construido una nueva patria en {link:durotar}Durotar{/link}. Son el corazón de la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[En Draenor, los orcos vivían en muchos clanes. Eran cazadores y guerreros, guiados por chamanes que hablaban con los espíritus de los {link:elements}elementos{/link}. El señor demoníaco {link:kil-jaeden}Kil'jaeden{/link} se propuso convertirlos en un arma de la {link:burning-legion}Legión Ardiente{/link}. Engañó al anciano chamán {link:ner-zhul}Ner'zhul{/link}, y después de él a su aprendiz, {link:gul-dan}Gul'dan{/link}. Gul'dan enseñó a los clanes las artes del brujo, y los elementos dieron la espalda a los orcos. Al final, los cabecillas bebieron la sangre del demonio {link:mannoroth}Mannoroth{/link}, y una sed de sangre se apoderó de todo el pueblo.

A través del {link:dark-portal}Portal Oscuro{/link}, la {link:horde}Horda{/link} cayó sobre el reino de {link:azeroth}Azeroth{/link}. Ganó la {link:first-war}Primera Guerra{/link} y quemó {link:stormwind-city}Ventormenta{/link}. Bajo {link:orgrim-doomhammer}Orgrim Doomhammer{/link} estuvo a punto de ganar también la {link:second-war}Segunda Guerra{/link}, pero fue traicionada desde dentro y derrotada. Los orcos supervivientes fueron recluidos en campos de internamiento, donde un extraño letargo se apoderó de ellos.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los orcos honran la fuerza, el valor y la lealtad al clan. Respetan al chamán que habla por los espíritus y al guerrero que se mantiene firme en la batalla. Sus nombres son orgullosos, y también su memoria: cada clan guarda sus propias leyendas y sus propios rencores. Desde el fin de la maldición del demonio, muchos orcos han vuelto a los viejos caminos del chamán y buscan el equilibrio con los elementos.]=],
		},
		{
			title = "En el presente",
			text = [=[El joven orco {link:thrall}Thrall{/link}, criado como esclavo en una fortaleza humana, escapó de sus amos y liberó a su pueblo de los campos. A la llamada de un profeta, lo condujo al oeste, a {link:kalimdor}Kalimdor{/link}. Allí, en la {link:third-war}Tercera Guerra{/link}, {link:grom-hellscream}Grom Hellscream{/link} mató a {link:mannoroth}Mannoroth{/link} y liberó a los orcos de la sangre del demonio. Thrall llamó a su nueva tierra {link:durotar}Durotar{/link} por su padre, Durotan, y a su capital {link:orgrimmar}Orgrimmar{/link} por Doomhammer. Los orcos mantienen ahora una paz inquieta con {link:theramore-isle}Theramore{/link}. Sin embargo, no todos los orcos se han apartado de la vieja oscuridad. El culto del {link:burning-blade}Filo Ardiente{/link} susurra en las cuevas de Durotar, y en los {link:eastern-kingdoms}Reinos del Este{/link} el {link:blackrock-clan}clan Roca Negra{/link} aún sirve a los dragones negros en la {link:blackrock-mountain}Montaña Roca Negra{/link}.]=],
		},
	},
})

Translate("esMX", "trolls", {
	title = "Trols",
	sections = {
		{
			title = "Resumen",
			text = [=[Los trols están entre los pueblos más antiguos de {link:azeroth}Azeroth{/link}. Son altos, con colmillos y feroces, y sus cuerpos sanan heridas que matarían a cualquier otra criatura. Mucho antes de que los elfos de la noche alzaran su imperio, los trols gobernaban grandes reinos propios. Esos imperios han caído, y las tribus que quedan son amargas, divididas y peligrosas. Una de ellas, la tribu {link:darkspear-trolls}Lanza Negra{/link}, está ahora con la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[El reino trol más antiguo fue el de los Zandalar, cuya tribu habitaba muy al sur. De ellos surgieron los dos grandes imperios de los tiempos antiguos: los Amani en los bosques del norte y los Gurubashi en las junglas del sur. Adoraban a poderosos espíritus llamados loa, y guerrearon con los primeros elfos de la noche y perdieron. La {link:great-sundering}Gran Fractura{/link} despedazó sus tierras.

Los Amani nunca perdonaron a los altos elfos que se asentaron en sus bosques. En las {link:troll-wars}Guerras Trol{/link} estuvieron cerca de destruir {link:quel-thalas}Quel'Thalas{/link}, hasta que los humanos de {link:arathor}Arathor{/link} se unieron a los elfos y los quebraron. En el sur, los Gurubashi cayeron en la guerra civil cuando los sacerdotes Atal'ai invocaron a {link:hakkar}Hakkar{/link}, el dios de la sangre. Las tribus derribaron al dios y expulsaron a los Atal'ai a los pantanos, donde construyeron el templo de {link:temple-of-atal-hakkar}Atal'Hakkar{/link}. Su imperio nunca se recuperó.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los trols son cazadores y saqueadores. Sus sacerdotes practican el vudú y hablan con los loa, y sus médicos brujos preparan pociones y maleficios que otros pueblos temen. Muchas tribus mantienen costumbres crueles, y se dice que algunas devoran a sus enemigos. Están orgullosos de su antiguo pasado y resienten a los pueblos más jóvenes que les quitaron sus tierras. Pocos trols confían en los forasteros, y en menos aún se confía a cambio.]=],
		},
		{
			title = "En el presente",
			text = [=[La {link:darkspear-trolls}tribu Lanza Negra{/link} fue expulsada de su hogar en las junglas y encontró refugio en los mares del sur. Allí {link:thrall}Thrall{/link} los salvó de los humanos y de la bruja del mar, y su líder Sen'jin dio la vida para que su pueblo pudiera seguir a los orcos. Hoy los Lanza Negra sirven a la {link:horde}Horda{/link} bajo {link:vol-jin}Vol'jin{/link}. Se asentaron en las {link:echo-isles}Islas del Eco{/link}, frente a {link:durotar}Durotar{/link}, pero un médico brujo llamado {link:zalazane}Zalazane{/link} se ha apoderado de las islas con magia oscura, y la tribu se ha retirado al {link:sen-jin-village}Poblado Sen'jin{/link}, en tierra firme. En otros lugares, las tribus trols siguen siendo enemigas de todos: los Amani en los bosques del norte, los {link:witherbark-trolls}Secacorteza{/link} y los Vilrama en las {link:the-hinterlands}Tierras del Interior{/link}, las tribus Gurubashi de la {link:stranglethorn-vale}Vega de Tuercespina{/link}, los {link:sandfury-trolls}Sandfury{/link} de {link:tanaris}Tanaris{/link} y los {link:frostmane-trolls}Peloescarcha{/link} de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
	},
})

Translate("esMX", "tauren", {
	title = "Tauren",
	aliases = { "tauren", "shu'halo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los tauren son un pueblo de gran estatura y sabiduría serena que recorre las llanuras de {link:kalimdor}Kalimdor{/link}. Son enormes y de aspecto taurino, y pueden ser terribles en la batalla, pero prefieren vivir en paz con la tierra. Veneran a la Madre Tierra por encima de todo. Bajo su gran jefe {link:cairne-bloodhoof}Cairne Bloodhoof{/link} se han asentado en las praderas de {link:mulgore}Mulgore{/link} y se han unido a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los tauren, que se llaman a sí mismos shu'halo, están entre los pueblos más antiguos de {link:kalimdor}Kalimdor{/link}. Durante eras vagaron por las llanuras como nómadas, siguiendo a las grandes manadas y el giro de las estaciones. Dicen que la Madre Tierra les dio la tierra, y que el sol y la luna son sus ojos, a los que llaman An'she y Mu'sha. Las tribus vivían separadas, cada una con sus propios jefes y sus propios tótems.

Esa vida estuvo a punto de terminar a causa de los {link:centaurs}centauros{/link}. Los crueles hombres caballo de las llanuras dieron caza a las tribus dispersas durante generaciones y las expulsaron de sus tierras ancestrales. {link:cairne-bloodhoof}Cairne Bloodhoof{/link} se propuso unir a las tribus contra ellos. Cuando los orcos llegaron a Kalimdor, Cairne conoció al joven {link:thrall}Thrall{/link}, y los dos pueblos se reconocieron como parientes de espíritu. Con la ayuda de los orcos, los tauren rompieron el dominio de los centauros sobre {link:mulgore}Mulgore{/link} y lo reclamaron como su patria.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los tauren viven cerca de la tierra. Cazan con respeto y toman solo lo que necesitan. Sus chamanes hablan con los espíritus de los {link:elements}elementos{/link} y de sus antepasados, y algunos tauren han aprendido los caminos del druida, instruidos por los elfos de la noche del {link:cenarion-circle}Círculo Cenarion{/link}. Son pacientes, lentos para la ira y honestos en extremo. Sus tótems registran los linajes y las hazañas de sus tribus.]=],
		},
		{
			title = "En el presente",
			text = [=[Los tauren han construido su capital, {link:thunder-bluff}Cima del Trueno{/link}, sobre altas mesetas por encima de {link:mulgore}Mulgore{/link}, a las que se llega por grandes elevadores. {link:cairne-bloodhoof}Cairne{/link} gobierna allí como Gran Jefe, respetado incluso por quienes temen a la {link:horde}Horda{/link}. No todas las tribus comparten su visión. La {link:grimtotem-clan}tribu Tótem Siniestro{/link}, dirigida por la anciana {link:magatha-grimtotem}Magatha{/link}, tiene sus propias ambiciones, y muchos en Cima del Trueno confían poco en ella. En torno a Mulgore, los tauren aún se enfrentan a enemigos: los jabaespines de la tribu {link:bristleback-quilboar}Erizapúas{/link}, las arpías de las crestas y los centauros de {link:the-barrens}Los Baldíos{/link}. Los tauren honran su deuda con los orcos, y están entre los miembros más firmes de la Horda.]=],
		},
	},
})

Translate("esMX", "forsaken", {
	title = "Renegados",
	sections = {
		{
			title = "Resumen",
			text = [=[Los Renegados son no-muertos que se han liberado de la voluntad del Rey Exánime. Antaño fueron el pueblo de {link:lordaeron}Lordaeron{/link}. Murieron en la peste, se alzaron como esclavos de la {link:scourge}Plaga{/link} y después, en una sola hora de debilidad en el control de su amo, despertaron de nuevo a su propia mente. Siguen a {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, la Reina Alma en Pena, y han hecho un reino oscuro bajo las ruinas de su antigua capital. Por razones propias, se han unido a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[En la {link:third-war}Tercera Guerra{/link}, la peste del {link:cult-of-the-damned}Culto de los Malditos{/link} se extendió por {link:lordaeron}Lordaeron{/link}, y el príncipe {link:arthas-menethil}Arthas Menethil{/link} asesinó a su padre, {link:terenas-menethil}Terenas Menethil{/link}, y entregó el reino a la {link:scourge}Plaga{/link}. Miles de los que murieron se alzaron de nuevo al servicio del Rey Exánime. Durante un tiempo no tuvieron voluntad alguna.

Entonces el poder del Rey Exánime flaqueó, y muchos de los no-muertos de Lordaeron descubrieron que podían volver a pensar por sí mismos. {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, la caída general forestal de {link:quel-thalas}Quel'Thalas{/link}, había sido alzada como alma en pena por el propio Arthas. Se liberó con ellos. Se volvió contra los señores del terror que pretendían gobernar el reino arruinado, y ató a uno de ellos, {link:varimathras}Varimathras{/link}, a su servicio. Llamó a su pueblo los Renegados, y los condujo a tomar como propias las ruinas de la capital de Lordaeron.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los Renegados recuerdan sus vidas, pero no pueden volver a ellas. Sus amigos y parientes los temen y los odian, y muchos han aprendido a odiar a su vez. Son sombríos, amargos y prácticos. Sus eruditos cultivan sin vergüenza todas las artes de la alquimia y la nigromancia, y sus sacerdotes han pasado de la {link:holy-light}Luz Sagrada{/link} a la sombra. Entre los vivos se les tolera más de lo que se confía en ellos.]=],
		},
		{
			title = "En el presente",
			text = [=[Bajo la ciudad destrozada de {link:lordaeron}Lordaeron{/link}, los Renegados han levantado {link:undercity}Entrañas{/link}, un laberinto de salones y cloacas construido en las antiguas criptas reales. Desde allí, {link:sylvanas-windrunner}Sylvanas{/link} gobierna los {link:tirisfal-glades}Claros de Tirisfal{/link} y libra una guerra en dos frentes: contra la {link:scourge}Plaga{/link}, que aún domina las tierras de la peste, y contra la {link:scarlet-crusade}Cruzada Escarlata{/link}, que quema a todo no-muerto que encuentra. Su alianza con la {link:horde}Horda{/link} es de necesidad. Los orcos y los {link:tauren}tauren{/link} los encuentran extraños e inquietantes. Los Renegados, por su parte, dicen poco de sus verdaderos fines, y los químicos de la {link:royal-apothecary-society}Real Sociedad de Boticarios{/link} trabajan en secreto en una nueva peste.]=],
		},
	},
})

Translate("esMX", "skyborne", {
	title = "Skyborne",
	aliases = { "shen'dorei" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Skyborne, que se llaman a sí mismos shen'dorei o "pueblo oculto", son elfos que han vivido durante miles de años más allá del propio mundo. Su hogar es la isla {link:zephras-isle}Zephras{/link}, una isla que flota en {link:skywall}Muro Celeste{/link}, el plano elemental del aire. Comparten la sangre de los Altonato, y son primos de los {link:high-elves}altos elfos{/link} de {link:quel-thalas}Quel'Thalas{/link}. Ahora su reino celeste se está desmoronando, y una nueva generación de Skyborne ha descendido a {link:azeroth}Azeroth{/link} en busca de respuestas.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los Skyborne remontan su linaje a los Altonato de Eldre'Thalas, la ciudad de {link:feralas}Feralas{/link} que hoy se llama {red:dire-maul}La Marra{/red}. Tras la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, el príncipe {red:tortheldrin}Tortheldrin{/red} intentó sostener la ciudad con poderes cada vez más peligrosos. Algunos de los suyos habían visto lo que esa sed de poder había hecho al mundo, y se alzaron contra él. Frustraron sus planes, pero su rebelión fue aplastada, y huyeron a través del mar con la flota del príncipe pisándoles los talones.

Muy al oeste, llegaron a una tierra gobernada por antiguos espíritus de los {link:elements}elementos{/link}. Allí sellaron un pacto con los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link}. Los espíritus arrancaron una gran parte de aquella tierra y la alzaron al cielo, la sacaron del mundo y la anclaron en Muro Celeste. Ocultos de sus perseguidores, los exiliados construyeron una civilización pequeña y luminosa entre las nubes.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Las largas eras en Muro Celeste cambiaron a los shen'dorei. Se volvieron más ligeros y más veloces que sus antepasados, y la magia del aire marcó su cabello, sus ojos y su piel. Vivieron junto a los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} como alumnos y amigos. Algunos de ellos recibieron el don de los espíritus de la vista celeste, el poder de ver a través del plano elemental. Los espíritus rara vez hablaban de {link:al-akir}Al'Akir{/link}, el Señor del Viento, amo de Muro Celeste, y entre los Skyborne su nombre se convirtió en algo de temor y silencio.]=],
		},
		{
			title = "En el presente",
			text = [=[Sin aviso, los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} desaparecieron. Los antiguos pilones que mantienen unida la isla {link:zephras-isle}Zephras{/link} han empezado a fallar, partes de la isla han caído en ruinas y sus comunidades han quedado aisladas unas de otras. Los Skyborne están divididos sobre qué hacer.

• {b}Los {link:windshapers}Windshapers{/link}.{/b} Descendientes de los primeros shen'dorei que recibieron la vista celeste, son los guías espirituales de la isla. Buscan averiguar qué fue de los espíritus del viento y restaurarlos. Se han unido a la {link:horde}Horda{/link}.
• {b}La {link:high-order}High Order{/link}.{/b} Descendientes de los magísteres Altonato que huyeron de Eldre'Thalas, creen que los Skyborne confiaron demasiado en sus protectores. Buscan el saber arcano que sus antepasados perdieron, para que su pueblo pueda valerse por sí mismo. Se han unido a la {link:alliance}Alianza{/link}.
• {b}Los {link:al-aketh}Al'Aketh{/link}.{/b} Un culto que se apartó del resto de los shen'dorei para servir a {link:al-akir}Al'Akir{/link}. Envalentonados por la ausencia de los espíritus, han sembrado el miedo y se han apoderado de gran parte de la isla.]=],
		},
	},
})

Translate("esMX", "high-elves", {
	title = "Altos elfos",
	aliases = { "quel'dorei", "alto elfo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los altos elfos, o quel'dorei, son los hijos de los exiliados Altonato que cruzaron el mar tras la {link:great-sundering}Gran Fractura{/link}. En los bosques del norte de {link:lordaeron}Lordaeron{/link} construyeron el reino de {link:quel-thalas}Quel'Thalas{/link} y su resplandeciente capital, Lunargenta. Durante miles de años fueron los maestros de la {link:arcane-magic}magia arcana{/link} en los {link:eastern-kingdoms}Reinos del Este{/link}. En la {link:third-war}Tercera Guerra{/link}, su reino estuvo a punto de ser destruido.]=],
		},
		{
			title = "Orígenes",
			text = [=[Tras la {link:great-sundering}Fractura{/link}, los elfos de la noche prohibieron el uso de la magia arcana. Los Altonato que no quisieron obedecer, dirigidos por {red:dath-remar-sunstrider}Dath'Remar Sunstrider{/red}, fueron exiliados. Navegaron hacia el este y, tras un largo vagar, llegaron a los bosques del norte, donde lucharon contra los {link:trolls}trols{/link} Amani por su nuevo hogar. Allí crearon la Fuente del Sol, un manantial de poder arcano que sostenía a su pueblo. Cuando los Amani se alzaron contra ellos, se aliaron con los {link:humans}humanos{/link} de {link:arathor}Arathor{/link} y les enseñaron la magia, y juntos ganaron las {link:troll-wars}Guerras Trol{/link}.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los altos elfos son elegantes, orgullosos y cultos. Aman la belleza y la magia, y muchos de ellos miran por encima del hombro a los pueblos más jóvenes. Sus forestales son los mejores arqueros del norte. Su vínculo con la Fuente del Sol era tan profundo que llegaron a depender de su poder.]=],
		},
		{
			title = "En el presente",
			text = [=[En la {link:third-war}Tercera Guerra{/link}, {link:arthas-menethil}Arthas Menethil{/link} condujo a la {link:scourge}Plaga{/link} a {link:quel-thalas}Quel'Thalas{/link}. Mató al rey Anasterian Sunstrider y usó la Fuente del Sol para alzar al exánime {link:kel-thuzad}Kel'Thuzad{/link}. La general forestal {link:sylvanas-windrunner}Sylvanas Windrunner{/link} cayó en la defensa de su patria. Los pocos que sobrevivieron siguen dispersos: algunos aún ocupan lo que queda de Quel'Thalas, algunos sirven a la {link:alliance}Alianza{/link} y al {link:kirin-tor}Kirin Tor{/link}, y un pequeño grupo guarda el pabellón de caza de {link:quel-danil-lodge}Quel'Danil{/link} en las {link:the-hinterlands}Tierras del Interior{/link}. El príncipe Kael'thas, heredero de los Sunstrider, reunió a muchos de los supervivientes y los rebautizó como sin'dorei, los elfos de sangre, en memoria de los caídos. Qué ha sido de él desde entonces, ninguna crónica de estas tierras puede decirlo.]=],
		},
	},
})

Translate("esMX", "kobolds", {
	title = "Kóbolds",
	aliases = { "kóbold" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los kóbolds son criaturas pequeñas, parecidas a ratas, que habitan en minas y cavernas de todo {link:azeroth}Azeroth{/link}. Son cobardes, codiciosos y no muy listos, pero son muchísimos. Dondequiera que una vieja mina queda sin vigilancia, los kóbolds se instalan en ella. Cada uno lleva una vela sobre la cabeza para alumbrar los túneles, y cada uno preferiría morir antes que renunciar a ella.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica recoge de dónde vinieron los kóbolds. Algunos excavadores de la {link:explorers-league}Liga de Expedicionarios{/link} creen que surgieron de los {link:troggs}troggs{/link} de los lugares profundos. Sea cual sea su origen, ya eran una molestia para los primeros colonos de {link:tirisfal-glades}Tirisfal{/link}, y desde entonces han sido una plaga para los mineros.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los kóbolds aman los túneles oscuros pero temen la oscuridad verdadera, y sus velas son lo más valioso que poseen. Robar una es el peor de los crímenes, y el ladrón se enterará. Excavan sin fin y acumulan todo lo que brilla. Sus geomantes practican una tosca magia de fuego y piedra. La mayoría se conforma con luchar solo cuando está acorralada, pero en enjambre pueden abrumar a un minero descuidado.]=],
		},
		{
			title = "En el presente",
			text = [=[Los kóbolds infestan las minas del {link:elwynn-forest}Bosque de Elwynn{/link} y de los {link:westfall}Páramos de Poniente{/link}, donde excavan en busca de un oro que no se queda en sus manos. Se dice que los mandan los {link:riverpaw-gnolls}gnolls Zarparrío{/link}, que a su vez tratan con la {link:defias-brotherhood}Hermandad Defias{/link}. Las Ratas del Túnel molestan a los enanos de {link:loch-modan}Loch Modan{/link}, y en {link:kalimdor}Kalimdor{/link} los kóbolds excavan para {link:venture-company}Ventura y Cía.{/link} en la {link:stonetalon-mountains}Sierra Espolón{/link}.]=],
		},
	},
})

Translate("esMX", "gnolls", {
	title = "Gnolls",
	aliases = { "gnoll" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los gnolls son criaturas parecidas a hienas que recorren los lugares salvajes de los {link:eastern-kingdoms}Reinos del Este{/link} y de {link:kalimdor}Kalimdor{/link}. Son brutos, pendencieros y hambrientos, y valoran la fuerza por encima de todo. Viven en manadas y clanes, cada uno gobernado por el más fuerte de ellos, y asaltan las granjas y los caminos de otros pueblos en busca de comida y botín.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los gnolls son un pueblo antiguo de {link:azeroth}Azeroth{/link}, y ninguna crónica recoge sus comienzos. Estaban entre los peligros a los que se enfrentaron los primeros colonos humanos en el norte. El reino de {link:stormwind-city}Ventormenta{/link} recuerda una época más oscura, cuando un señor de la manada de los gnolls de {link:redridge-mountains}Crestagrana{/link} llamado Garfang reunió a los clanes en una gran hueste y atacó las granjas del reino. El rey Barathen Wrynn salió a caballo y lo mató, y las manadas se despedazaron entre sí en la lucha que siguió.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los gnolls prefieren que otros hagan su trabajo. Sus líderes empujan a los débiles por delante, y sirven con gusto a cualquier amo más fuerte que les prometa comida y botín. Sus místicos practican un chamanismo tosco. Son lo bastante astutos para tender trampas y emboscadas, y lo bastante crueles para disfrutarlas.]=],
		},
		{
			title = "En el presente",
			text = [=[Los gnolls acosan casi todas las fronteras de las tierras humanas. Los {link:riverpaw-gnolls}Zarparrío{/link} asaltan el {link:elwynn-forest}Bosque de Elwynn{/link} y los {link:westfall}Páramos de Poniente{/link}. La manada de Crestagrana y los {link:shadowhide-gnolls}Pellejo Negro{/link} merodean por las {link:redridge-mountains}Montañas Crestagrana{/link}, estos últimos sometidos al brujo {link:morganth}Morganth{/link}. Los Pellejomusgo rondan {link:wetlands}Los Humedales{/link}, los Rot Hide desentierran a los muertos de los {link:tirisfal-glades}Claros de Tirisfal{/link} para la {link:scourge}Plaga{/link}, y otros clanes recorren las colinas de {link:hillsbrad-foothills}Trabalomas{/link} y los bosques de {link:feralas}Feralas{/link}.]=],
		},
	},
})

Translate("esMX", "riverpaw-gnolls", {
	title = "Gnolls Zarparrío",
	aliases = { "gnolls Zarparrío", "Zarparrío" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Zarparrío son el clan de gnolls que asola las tierras del sur del {link:kingdom-of-stormwind}Reino de Ventormenta{/link}. Recorren la frontera del {link:elwynn-forest}Bosque de Elwynn{/link}, los campos de los {link:westfall}Páramos de Poniente{/link} y el camino hacia las {link:redridge-mountains}Montañas Crestagrana{/link}. Asaltan granjas, tienden emboscadas a los viajeros y combaten a los pocos soldados que el reino puede destinar. El más temido de ellos es el gran {link:gnolls}gnoll{/link} {link:hogger}Hogger{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[Los Zarparrío se han vuelto más audaces desde que el ejército del reino fue enviado al extranjero. Salen de la Linde del bosque para golpear las granjas del sur de {link:elwynn-forest}Elwynn{/link}, y el {link:westbrook-garrison}Cuartel de Arroyoeste{/link} paga una recompensa por cada zarpa que traen sus voluntarios. En los {link:westfall}Páramos de Poniente{/link} sus campamentos son aún mayores. La Milicia del Pueblo ha hallado indicios de que los Zarparrío no luchan solo por sí mismos: hacen trabajar a esclavos {link:kobolds}kóbolds{/link} en las minas, y tratan con la {link:defias-brotherhood}Hermandad Defias{/link}. Muchos en {link:stormwind-city}Ventormenta{/link} se preguntan quién los arma, y quién les da su inusual astucia.]=],
		},
	},
})

Translate("esMX", "murlocs", {
	title = "Múrlocs",
	aliases = { "múrloc" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los múrlocs son criaturas pequeñas, parecidas a peces, que viven en las costas, lagos y ríos de {link:azeroth}Azeroth{/link}. Caminan sobre dos piernas, hablan una lengua gorgoteante que ningún otro pueblo entiende y atacan en enjambres repentinos. Todo pescador de los {link:eastern-kingdoms}Reinos del Este{/link} y de {link:kalimdor}Kalimdor{/link} tiene una historia sobre los múrlocs.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica recoge de dónde vinieron los múrlocs. Han rondado las costas del mundo desde que cualquier pueblo lleva registros, y parecen no preocuparse en absoluto por las guerras de los habitantes de tierra firme.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los múrlocs viven en tribus, en aldeas de chozas construidas a la orilla del agua. Cazan peces y cualquier otra cosa que se acerque a sus costas. Sus oráculos y cazamareas manejan una magia sencilla de agua y tormenta. Rara vez son peligrosos solos, pero rara vez vienen solos. Cuando se ataca a un múrloc, aparecen otros de los bajíos con un grito terrible.]=],
		},
		{
			title = "En el presente",
			text = [=[Los múrlocs se han envalentonado a medida que los reinos se debilitan. Asaltan las orillas de los lagos del {link:elwynn-forest}Bosque de Elwynn{/link} y la costa de los {link:westfall}Páramos de Poniente{/link}. La tribu Branquizul ronda las marismas de {link:wetlands}Los Humedales{/link}, y la tribu Greymist las costas de {link:darkshore}Costa Oscura{/link}. En todas las costas, de la {link:stranglethorn-vale}Vega de Tuercespina{/link} a {link:durotar}Durotar{/link}, sus chozas se alzan a la orilla del agua.]=],
		},
	},
})

Translate("esMX", "quilboar", {
	title = "Jabaespines",
	aliases = { "jabaespín" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los jabaespines son un pueblo salvaje de hombres jabalí que habitan en el sur de {link:the-barrens}Los Baldíos{/link} y en las tierras que lo rodean. Están cubiertos de cerdas y espinas, y hacen sus hogares entre grandes enredaderas de espinas. Son hostiles a casi todos los demás pueblos, y llevan mucho tiempo en guerra con los {link:tauren}tauren{/link} y los orcos.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los jabaespines sostienen que son los hijos de Agamaggan, el gran semidiós jabalí. En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, Agamaggan luchó contra la {link:burning-legion}Legión Ardiente{/link} y fue abatido. Donde cayó su sangre, inmensas enredaderas de espinas brotaron de la tierra. Esas espinas se convirtieron en Rajacieno, y los jabaespines hicieron de ellas su hogar sagrado.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los jabaespines son feroces y territoriales. Sus tribus están dirigidas por señores de la guerra, y sus geomantes invocan a la tierra. Veneran la memoria de Agamaggan y consideran sagrado Rajacieno. Algunas de sus sacerdotisas se han vuelto hacia artes más oscuras, y algunos de sus guerreros hacia amos más oscuros.]=],
		},
		{
			title = "En el presente",
			text = [=[La tribu Crines de Acero asalta los límites de {link:durotar}Durotar{/link} y el norte de {link:the-barrens}Los Baldíos{/link}, y la tribu {link:bristleback-quilboar}Erizapúas{/link} molesta las llanuras de {link:mulgore}Mulgore{/link}. En el sur, los jabaespines habitan en las grandes madrigueras de espinas del {link:razorfen-kraul}Horado Rajacieno{/link} y de la {link:razorfen-downs}Zahúrda Rajacieno{/link}. Se dice que en la Zahúrda un culto llamado la Cabeza de la Muerte se ha vuelto hacia la {link:scourge}Plaga{/link}, y que ahora un exánime vive entre ellos.]=],
		},
	},
})

Translate("esMX", "centaurs", {
	title = "Centauros",
	aliases = { "centauro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los centauros son un pueblo cruel y belicoso de {link:kalimdor}Kalimdor{/link}. Tienen el torso de un hombre y el cuerpo de un caballo, y son terribles saqueadores que cabalgan en bandas rápidas y despiadadas. Durante generaciones han sido los mayores enemigos de los {link:tauren}tauren{/link}.]=],
		},
		{
			title = "Orígenes",
			text = [=[Se dice que los centauros descienden de la unión de Zaetar, un hijo del semidiós {link:cenarius}Cenarius{/link}, y Theradras, una princesa de la tierra elemental. Sus primeros hijos fueron crueles más allá de toda medida, y en un arrebato de celos mataron a su propio padre. Theradras dio descanso a Zaetar en las cavernas de {red:maraudon}Maraudon{/red}, donde se dice que su espíritu aún permanece.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los centauros viven como nómadas y saqueadores. Sostienen que los fuertes deben tomar lo que quieran de los débiles. Sus kanes dirigen las tribus, y las tribus guerrean entre sí cuando no tienen otros enemigos. Son jinetes y arqueros hábiles, y muestran poca piedad.]=],
		},
		{
			title = "En el presente",
			text = [=[La {link:kolkar-centaurs}tribu Kolkar{/link} recorre {link:the-barrens}Los Baldíos{/link}, y sus saqueadores atacan los puestos orcos de allí. Los Galak cabalgan por {link:thousand-needles}Las Mil Agujas{/link}. En {link:desolace}Desolace{/link}, los Magram y los Gelkis mantienen una larga enemistad, y ambos reclaman el favor de Theradras. Los Maraudine guardan la entrada de la propia Maraudon. Aunque {link:cairne-bloodhoof}Cairne{/link} expulsó a los centauros de {link:mulgore}Mulgore{/link}, no han olvidado a los {link:tauren}tauren{/link}.]=],
		},
	},
})

Translate("esMX", "furbolgs", {
	title = "Fúrbolgs",
	aliases = { "fúrbolg" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los fúrbolgs son un pueblo de aspecto de oso de los bosques del norte de {link:kalimdor}Kalimdor{/link}. Durante mucho tiempo fueron gente mansa y pacífica, amigos de los {link:night-elves}elfos de la noche{/link} y de los druidas. En los últimos años, una enfermedad del espíritu ha caído sobre la mayoría de sus tribus, y muchos fúrbolgs se han vuelto salvajes y hostiles.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los fúrbolgs han vivido en los bosques de {link:kalimdor}Kalimdor{/link} desde tiempos antiguos. Antaño se contaban entre los aliados de los {link:night-elves}kaldorei{/link}. Ninguna crónica recoge sus comienzos con más detalle.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los fúrbolgs viven en tribus, en cubiles y aldeas ocultos en lo profundo de los bosques. Sus chamanes son sabios en los caminos del bosque. La mayoría se contentaba con vivir tranquila y comerciar en paz con sus vecinos.]=],
		},
		{
			title = "En el presente",
			text = [=[La corrupción demoníaca que quedó en los bosques desde la {link:third-war}Tercera Guerra{/link} ha enloquecido a muchas tribus. Los {link:thistlefur-village}Piel de Cardo{/link} y los Foulweald de {link:ashenvale}Vallefresno{/link}, los {link:deadwood-furbolgs}Muertobosque{/link} de {link:felwood}Frondavil{/link}, los {link:blackwood-furbolgs}Bosque Negro{/link} de {link:darkshore}Costa Oscura{/link}, los {link:gnarlpine-furbolgs}Tuercepinos{/link} de {link:teldrassil}Teldrassil{/link} y los {link:winterfall-furbolgs}Invernales{/link} de {link:winterspring}Cuna del Invierno{/link} se han vuelto contra sus viejos amigos. Solo los {link:timbermaw-furbolgs}Fauces de Madera{/link} han resistido la corrupción. Guardan los pasos del {link:timbermaw-hold}Bastión Fauces de Madera{/link} y no confían en ningún forastero hasta que haya demostrado su valía.]=],
		},
	},
})

Translate("esMX", "harpies", {
	title = "Arpías",
	aliases = { "arpía" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las arpías son criaturas aladas de {link:kalimdor}Kalimdor{/link}, con cuerpo de mujer y alas y garras de ave. Son crueles, astutas y despiadadas, y hacen presa de los viajeros desde sus nidos en las alturas.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los orígenes de las arpías no constan en ninguna crónica conocida por este registro.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Las arpías viven en bandadas gobernadas por matriarcas. Anidan en acantilados y crestas y se abalanzan sobre todo lo que es más débil que ellas. Les gustan las cosas brillantes robadas y la carne de quienes atrapan. Sus brujas dominan la magia oscura.]=],
		},
		{
			title = "En el presente",
			text = [=[Las {link:windfury-harpies}arpías Viento Furioso{/link} anidan en las crestas de {link:mulgore}Mulgore{/link}, para gran disgusto de los {link:tauren}tauren{/link}. Las Witchwing se posan en {link:the-barrens}Los Baldíos{/link}, las Bloodfury en la {link:stonetalon-mountains}Sierra Espolón{/link} y las Northspring en {link:feralas}Feralas{/link}. Los caminos de {link:kalimdor}Kalimdor{/link} no son seguros bajo sus nidos.]=],
		},
	},
})

Translate("esMX", "troggs", {
	title = "Troggs",
	aliases = { "trogg" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los troggs son criaturas brutas de piel de piedra que viven en lo más profundo de la tierra. Son fuertes, estúpidos e incansablemente agresivos. Durante eras estuvieron ocultos en las profundidades. Ahora han salido a la superficie, y han traído la ruina consigo.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los registros de {link:uldaman}Uldaman{/link} cuentan que los troggs fueron creados por los titanes, como los terráneos. Fueron una creación imperfecta, y los titanes los encerraron en las cámaras profundas del mundo. La {link:explorers-league}Liga de Expedicionarios{/link} cree que los enanos perturbaron esas cámaras al excavar en Uldaman, y que los troggs no han dejado de extenderse desde entonces.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los troggs viven en tribus dirigidas por el más fuerte de ellos. Sus chamanes manejan una tosca magia de tierra. Les importa poco nada que no sea luchar y comer.]=],
		},
		{
			title = "En el presente",
			text = [=[Los troggs surgieron bajo {link:gnomeregan}Gnomeregan{/link} y expulsaron a los gnomos de su ciudad. Luchan contra los enanos en {link:dun-morogh}Dun Morogh{/link} y {link:loch-modan}Loch Modan{/link}, y pululan por {link:uldaman}Uldaman{/link} y las {link:badlands}Tierras Inhóspitas{/link}. Dondequiera que los enanos excavan hondo, temen encontrar más.]=],
		},
	},
})

Translate("esMX", "ogres", {
	title = "Ogros",
	aliases = { "ogro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los ogros son brutos enormes, de pocas luces y gran fuerza. Algunos tienen dos cabezas, y unos pocos son hechiceros astutos. La mayoría llegó a {link:azeroth}Azeroth{/link} con los orcos desde Draenor, y muchos clanes habitan ahora los lugares salvajes de ambos continentes.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los ogros sirvieron a la {link:horde}Horda{/link} orca en la {link:second-war}Segunda Guerra{/link}. El brujo {link:gul-dan}Gul'dan{/link} dio a algunos de ellos el don de la hechicería, y estos magos ogros llegaron a ser temidos en todos los {link:eastern-kingdoms}Reinos del Este{/link}. El mayor de ellos, Cho'gall, dirigió el clan {link:twilight-s-hammer}Martillo Crepuscular{/link}. Tras la derrota de la Horda, los clanes ogros se dispersaron por las colinas y las montañas.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los ogros son belicosos y codiciosos. Solo respetan la fuerza y luchan entre sí por el mando. Sus cabecillas gobiernan con el garrote, y sus magos con el miedo.]=],
		},
		{
			title = "En el presente",
			text = [=[Los clanes ogros ocupan las colinas de {link:redridge-mountains}Crestagrana{/link}, la {link:stranglethorn-vale}Vega de Tuercespina{/link}, {link:alterac-mountains}Alterac{/link} y las {link:arathi-highlands}Tierras Altas de Arathi{/link}. En {link:kalimdor}Kalimdor{/link}, los Gordunni rondan {link:feralas}Feralas{/link}, y los Gordok gobiernan las ruinas de {red:dire-maul}La Marra{/red}. En el {link:dustwallow-marsh}Marjal Revolcafango{/link}, el clan Quebrantarrocas ha perdido su antigua fuerza, y algunos de sus ogros viven ahora junto a los orcos.]=],
		},
	},
})

Translate("esMX", "naga", {
	title = "Naga",
	aliases = { "naga" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los naga son criaturas serpentinas de los mares profundos. Antaño fueron elfos de la noche de la casta Altonato. Ahora tienen colas escamosas y rostros crueles, y han regresado de las profundidades para perturbar las costas del mundo.]=],
		},
		{
			title = "Orígenes",
			text = [=[Cuando el {link:well-of-eternity}Pozo de la Eternidad{/link} fue destruido en la {link:great-sundering}Gran Fractura{/link}, el palacio de la {link:queen-azshara}reina Azshara{/link} fue tragado por el mar con toda su corte. Algo en las profundidades los salvó, y los cambió. Los Altonato ahogados se convirtieron en los naga. Durante diez mil años habitaron ocultos bajo las olas. En tiempos de la {link:third-war}Tercera Guerra{/link} se alzaron de nuevo, y durante un tiempo sirvieron a {link:illidan-stormrage}Illidan Stormrage{/link}.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los naga son orgullosos, amargos y ambiciosos. Sus sirenas son hechiceras poderosas que dominan las aguas y las tormentas. Sus mirmidones son guerreros temibles. Se dice que aún honran a {link:azshara}Azshara{/link} en las profundidades.]=],
		},
		{
			title = "En el presente",
			text = [=[Los naga han reclamado tramos de costa en {link:azshara}Azshara{/link}, {link:darkshore}Costa Oscura{/link}, {link:ashenvale}Vallefresno{/link} y {link:desolace}Desolace{/link}. Rondan el templo inundado de las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. Qué buscan en las costas de {link:kalimdor}Kalimdor{/link}, los elfos de la noche no lo saben.]=],
		},
	},
})

Translate("esMX", "satyrs", {
	title = "Sátiros",
	aliases = { "sátiro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los sátiros son demonios del bosque, con cuernos y patas de cabra. Antaño fueron elfos de la noche Altonato que se vendieron a la {link:burning-legion}Legión Ardiente{/link}. Ahora rondan los bosques corrompidos del norte de {link:kalimdor}Kalimdor{/link}, extendiendo la mancha de la {link:fel-magic}magia vil{/link} allá donde van.]=],
		},
		{
			title = "Orígenes",
			text = [=[En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, lord Xavius, consejero de la {link:queen-azshara}reina Azshara{/link}, fue el primero de los Altonato en servir a los demonios. Tras su derrota, el amo de la Legión lo rehízo como el primer sátiro. Xavius, a su vez, arrastró a muchos de los Altonato al mismo destino. Los sátiros lucharon por la Legión durante toda la guerra, y muchos sobrevivieron a la {link:great-sundering}Fractura{/link}.]=],
		},
		{
			title = "Naturaleza y costumbres",
			text = [=[Los sátiros son crueles, falsos y ávidos de poder. Sirven a los demonios, esté la Legión cerca o lejos. Su magia es vil, y corrompen la tierra en la que habitan. Sus tribus viven en arboledas oscuras en los bosques que expolian.]=],
		},
		{
			title = "En el presente",
			text = [=[Los sátiros se han extendido por los bosques desde la {link:third-war}Tercera Guerra{/link}. Infestan {link:felwood}Frondavil{/link} y {link:ashenvale}Vallefresno{/link}, donde el {link:satyrnaar}Satyrnaar{/link} es su bastión, y acechan en las ruinas de {link:azshara}Azshara{/link} y en las profundidades de {red:dire-maul}La Marra{/red}. Las {link:sentinels}Centinelas{/link} les dan caza sin piedad.]=],
		},
	},
})
